#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include "md4c-html.h"
static unsigned char cur[10000]; static int curn;
static void cb(const MD_CHAR* t, MD_SIZE s, void* u){}
void bad_start_hook(int type){
 fprintf(stderr,"FOUND type=%d size=%d\n",type,curn);
 for(int i=0;i<curn;i++){ unsigned char c=cur[i]; if(c=='\n') fprintf(stderr,"\\n"); else if(c=='\t') fprintf(stderr,"\\t"); else if(c>=32&&c<127) fputc(c,stderr); else fprintf(stderr,"\\x%02x",c);} fprintf(stderr,"\n"); exit(77);
}
int main(){
 const char* atoms[]={"","a","b","c","---","----","___","***","# h","#","```","~~~","> a",">","> |a|","> |-|","> ---","> # h","- a","-","- |a|","- |-|","  |-|","  a","    code","|a|","|-|","|---|","|:--|","| --- |","a|b","-|-",":--- | ---:","[x]: y","[x]:","<div>","</div>","<!--","-->","1. a","1.","2. a","   ","\t","    |-|","    a","* a","+ a","1) a","   - a"," > a"};
 unsigned flags[]={0,0x100,0x900,0x80100,0x80100|0x100,0xffffffff,0x100|0x10};
 int na=sizeof(atoms)/sizeof(atoms[0]), nf=sizeof(flags)/sizeof(flags[0]); srand(1);
 for(long it=0;;it++){
  if((it%100000)==0) fprintf(stderr,"it %ld\n",it);
  int n=1+rand()%12; curn=0;
  for(int l=0;l<n;l++){ const char*a=atoms[rand()%na]; int len=strlen(a); memcpy(cur+curn,a,len); curn+=len; cur[curn++]='\n'; }
  md_html((char*)cur,curn,cb,NULL,flags[rand()%nf],0);
 }
}
